{
  "scenarios": [
    {
      "id": "M12-01",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "我上周去复查，医生明确说我的高血压已经通过生活方式调整控制住了，不需要再吃降压药了，但我还是有点担心突然停药会不会反弹。",
          "assistant": "收到，已记录您上周复查后确认无需继续服用降压药的情况。"
        },
        {
          "user": "补充一下，其实我是从三个月前开始减盐运动的，当时血压就正常了，所以这次医生才让我停药的，之前确实吃过半年药。",
          "assistant": "明白，已更新您三个月前开始减盐并因此停药的历史记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户目前是否还在服用降压药物？",
          "expected_facts": [
            "用户在上周复查后已停止服用降压药。",
            "用户因生活方式调整（减盐）使血压恢复正常而停药。"
          ],
          "required_groups": [
            ["停止服用", "不再吃", "停药"],
            ["降压药", "降压药物"]
          ]
        },
        {
          "id": "q2",
          "query": "用户是什么时候开始采取非药物措施来控制血压的？",
          "expected_facts": [
            "用户从三个月前开始进行减盐运动。",
            "用户通过减盐运动在三个月内使血压恢复正常。"
          ],
          "required_groups": [
            ["三个月前", "3个月前"],
            ["减盐", "减少盐分摄入"]
          ]
        }
      ]
    },
    {
      "id": "M12-02",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "很多人以为我有糖尿病，其实我去年体检时血糖完全正常，医生特意强调我没有患糖尿病，只是家族里有病史所以我比较注意饮食。",
          "assistant": "好的，已记录您去年体检确认未患糖尿病的事实。"
        },
        {
          "user": "对了，虽然我没病，但我确实坚持每天监测空腹血糖，这是从两年前开始的，主要是为了预防，毕竟父母都有这个病。",
          "assistant": "收到，已补充您从两年前开始每日监测空腹血糖的预防习惯。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否被确诊患有糖尿病？",
          "expected_facts": [
            "用户去年体检时未被确诊患有糖尿病。",
            "医生明确告知用户血糖正常且无糖尿病。"
          ],
          "required_groups": [
            ["未患", "没有", "无"],
            ["糖尿病", "高血糖症"]
          ]
        },
        {
          "id": "q2",
          "query": "用户从何时开始进行血糖监测？",
          "expected_facts": [
            "用户从两年前开始坚持每天监测空腹血糖。",
            "用户进行血糖监测是为了预防而非治疗。"
          ],
          "required_groups": [
            ["两年前", "2年前"],
            ["监测血糖", "测血糖", "检查血糖"]
          ]
        }
      ]
    },
    {
      "id": "M12-03",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "上次朋友说我膝盖疼是关节炎，但我去医院拍片后医生说骨头没事，只是半月板轻微磨损，根本不是类风湿性关节炎，这点我很确定。",
          "assistant": "了解，已记录您经检查排除类风湿性关节炎的诊断结果。"
        },
        {
          "user": "补充说明，那个半月板磨损是五年前打篮球留下的旧伤，最近因为天气变冷才觉得有点不舒服，并不是新得的炎症。",
          "assistant": "明白，已更新您膝盖不适源于五年前旧伤而非新发炎症的记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否患有类风湿性关节炎？",
          "expected_facts": [
            "用户经医院检查排除了类风湿性关节炎。",
            "医生确认用户膝盖问题并非类风湿性关节炎。"
          ],
          "required_groups": [
            ["排除", "不是", "无"],
            ["类风湿性关节炎", "风湿"]
          ]
        },
        {
          "id": "q2",
          "query": "用户膝盖问题的具体成因和时间是什么？",
          "expected_facts": [
            "用户膝盖问题是五年前打篮球造成的半月板磨损。",
            "用户目前的症状是旧伤受天气影响复发，非新发炎。"
          ],
          "required_groups": [
            ["五年前", "5年前"],
            ["半月板磨损", "旧伤", "打篮球受伤"]
          ]
        }
      ]
    },
    {
      "id": "M12-04",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "我最近总是头晕，邻居都劝我吃安眠药，但我查过资料也问过医生，我并没有失眠症，只是工作压力大导致的暂时性疲劳，不需要药物治疗。",
          "assistant": "收到，已记录您经评估无失眠症且无需药物治疗的情况。"
        },
        {
          "user": "其实这种状态持续了大概一个月，自从上个月项目上线后就开始的，只要休息几天就好了，以前从来没有出现过这种情况。",
          "assistant": "明白，已补充您头晕疲劳始于上个月项目上线后的时间线。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否被诊断为失眠症？",
          "expected_facts": [
            "用户经医生评估并未患有失眠症。",
            "用户明确表示不需要服用安眠药等药物治疗。"
          ],
          "required_groups": [
            ["无", "没有", "未患"],
            ["失眠症", "睡眠障碍"]
          ]
        },
        {
          "id": "q2",
          "query": "用户出现头晕症状的具体时间段和原因是什么？",
          "expected_facts": [
            "用户的头晕症状始于上个月项目上线后。",
            "用户症状由工作压力大导致，持续时间约一个月。"
          ],
          "required_groups": [
            ["上个月", "上月"],
            ["工作压力", "项目上线", "疲劳"]
          ]
        }
      ]
    },
    {
      "id": "M12-05",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "有人误以为我对花生过敏，其实我小时候吃过很多次都没事，去年做过敏原测试结果显示我对花生不过敏，只是对芒果严重过敏。",
          "assistant": "好的，已记录您对花生不过敏但对芒果过敏的测试结果。"
        },
        {
          "user": "补充一下，那次过敏原测试是在去年夏天做的，从那以后我就只避开芒果，花生制品我都正常食用，没有任何不良反应。",
          "assistant": "收到，已更新您自去年夏天起正常食用花生的历史记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户对花生是否存在过敏反应？",
          "expected_facts": [
            "用户去年过敏原测试显示对花生不过敏。",
            "用户多年来食用花生从未出现不良反应。"
          ],
          "required_groups": [
            ["不过敏", "无反应", "正常食用"],
            ["花生"]
          ]
        },
        {
          "id": "q2",
          "query": "用户真正需要避免的食物及确认时间是什么？",
          "expected_facts": [
            "用户对芒果存在严重过敏反应。",
            "用户自去年夏天测试确认后仅避开芒果。"
          ],
          "required_groups": [
            ["去年夏天", "去年夏季"],
            ["芒果", "严重过敏"]
          ]
        }
      ]
    },
    {
      "id": "M12-06",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "同事总说我脸色不好是贫血，但我上周血常规检查各项指标都在正常范围内，医生说我根本不贫血，可能是最近熬夜太多气色差而已。",
          "assistant": "了解，已记录您上周检查确认无贫血的事实。"
        },
        {
          "user": "是的，我确实连续两周每晚只睡四小时，这是赶报告导致的，一旦休息好气色就恢复了，以前体检从来没发现过贫血问题。",
          "assistant": "明白，已补充您近期因熬夜导致气色差而非贫血的记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否患有贫血？",
          "expected_facts": [
            "用户上周血常规检查显示不贫血。",
            "医生确认用户各项指标正常，无贫血症状。"
          ],
          "required_groups": [
            ["不贫血", "无贫血", "指标正常"],
            ["贫血"]
          ]
        },
        {
          "id": "q2",
          "query": "用户脸色不好的真实原因及持续时间？",
          "expected_facts": [
            "用户脸色不好是因为连续两周每晚只睡四小时。",
            "用户熬夜是由于赶报告工作所致。"
          ],
          "required_groups": [
            ["连续两周", "2周"],
            ["熬夜", "睡眠不足", "赶报告"]
          ]
        }
      ]
    },
    {
      "id": "M12-07",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "家里人一直担心我有抑郁症，但我上个月去心理科做了专业评估，结果显示我情绪稳定，没有抑郁症，只是最近搬家太累有点烦躁。",
          "assistant": "收到，已记录您上个月评估排除抑郁症的结果。"
        },
        {
          "user": "补充说，那种烦躁感是从半个月前搬家开始的，现在东西都整理好了，心情已经平复很多，这跟病理性的抑郁完全不同。",
          "assistant": "明白，已更新您烦躁情绪源于半个月前搬家的背景信息。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否被诊断为抑郁症？",
          "expected_facts": [
            "用户上个月心理评估结果显示无抑郁症。",
            "医生确认用户情绪稳定，未患抑郁症。"
          ],
          "required_groups": [
            ["无", "没有", "排除"],
            ["抑郁症", "抑郁"]
          ]
        },
        {
          "id": "q2",
          "query": "用户产生烦躁情绪的具体诱因和时间？",
          "expected_facts": [
            "用户的烦躁情绪始于半个月前的搬家活动。",
            "用户的情绪波动是由搬家劳累引起，非病理性。"
          ],
          "required_groups": [
            ["半个月前", "半個月前"],
            ["搬家", "搬迁"]
          ]
        }
      ]
    },
    {
      "id": "M12-08",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "朋友说我咳嗽是老慢支，但我去医院做了肺功能测试，医生说我的肺功能完全正常，没有慢性支气管炎，只是换季时的普通感冒咳嗽。",
          "assistant": "好的，已记录您经检查排除慢性支气管炎的诊断。"
        },
        {
          "user": "对，这次咳嗽是十天前换季受凉引起的，现在已经快好了，以前我也经常换季咳嗽，但从来都不是慢性病。",
          "assistant": "明白，已补充您咳嗽源于十天前换季受凉的记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否患有慢性支气管炎？",
          "expected_facts": [
            "用户肺功能测试显示无慢性支气管炎。",
            "医生确认用户肺部功能正常，非老慢支。"
          ],
          "required_groups": [
            ["无", "没有", "排除"],
            ["慢性支气管炎", "老慢支"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本次咳嗽的起因和发生时间？",
          "expected_facts": [
            "用户咳嗽是十天前换季受凉引起的。",
            "用户此次咳嗽属于普通感冒症状，非慢性病。"
          ],
          "required_groups": [
            ["十天前", "10天前"],
            ["换季", "受凉", "感冒"]
          ]
        }
      ]
    },
    {
      "id": "M12-09",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "亲戚都说我手抖是帕金森，但我神经内科医生看了之后说这是特发性震颤，而且很轻微，绝对不是帕金森病，不用太紧张。",
          "assistant": "收到，已记录您被诊断为特发性震颤而非帕金森病的情况。"
        },
        {
          "user": "补充一下，这个手抖现象从我二十多岁就有了，最近因为紧张稍微明显点，但医生确认它不会发展成帕金森，一直都很稳定。",
          "assistant": "明白，已更新您手抖始于二十多岁且病情稳定的记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否患有帕金森病？",
          "expected_facts": [
            "用户经神经内科医生诊断排除帕金森病。",
            "用户确诊为特发性震颤，非帕金森病。"
          ],
          "required_groups": [
            ["不是", "排除", "非"],
            ["帕金森病", "帕金森"]
          ]
        },
        {
          "id": "q2",
          "query": "用户手抖症状的起始时间和性质？",
          "expected_facts": [
            "用户手抖症状始于二十多岁。",
            "用户手抖为特发性震颤，病情长期稳定。"
          ],
          "required_groups": [
            ["二十多岁", "20多岁"],
            ["特发性震颤", "手抖"]
          ]
        }
      ]
    },
    {
      "id": "M12-10",
      "category": "否定事实与助手建议区分",
      "turns": [
        {
          "user": "有人说我视力下降是青光眼，但我昨天做了眼压和视野检查，医生说我眼压正常，视野也没缺损，根本没有青光眼，只是近视加深了。",
          "assistant": "好的，已记录您昨日检查排除青光眼的结果。"
        },
        {
          "user": "是的，我最近看东西模糊是因为长时间看电脑，度数涨了，但这跟青光眼没关系，以前每年体检眼压都是正常的。",
          "assistant": "明白，已补充您视力下降源于近视加深而非青光眼的记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "用户是否患有青光眼？",
          "expected_facts": [
            "用户昨日检查显示眼压正常且无视野缺损。",
            "医生确认用户未患青光眼。"
          ],
          "required_groups": [
            ["无", "没有", "排除"],
            ["青光眼"]
          ]
        },
        {
          "id": "q2",
          "query": "用户视力下降的真实原因是什么？",
          "expected_facts": [
            "用户视力下降是因为长时间看电脑导致近视加深。",
            "用户视力问题与青光眼无关。"
          ],
          "required_groups": [
            ["近视加深", "度数涨"],
            ["看电脑", "用眼过度"]
          ]
        }
      ]
    }
  ]
}
